	Return label definition text at a given address.

	Format: '{label}: ; {address}'
	"""
def generate_label_asm(label: Any, address: Any) -> object {
    label_text = '%s: ; %x' % (label, address);
    return (address, label_text, address);
}

"""preprocess formatting of the list of ingredients

    will remove string 'and' and '&' if present

    Args:
        ingredients (list of strings): list of ingredients

    Returns:
        list: list of formatted ingredients
    """
def prep_ingr(ingredients: Any) -> object {
    toreturn = [];
    for ingr in ingredients {
        if (("and" in ingr) or ("&" in ingr)) {
            ingr = ingr.replace("and", "").replace("&", "");
            ingr = ingr.split(" ");
            while ("" in ingr) {
                ingr.remove("");
            }
            for i in ingr {
                toreturn.append(i);
            }
        } else {
            toreturn.append("_".join(ingr.split(" ")));
        }
    }
    return toreturn;
}

