"""
	Sort the file tree as returned by getFileTree, by
	1. Directory, then Files
	2. Alphabetical

	Input:
		List of dictionaries
		[
			{
				path: file's absoluate path
				type: dir/file
				isRoot: boolean; is "root" directory
				isParent: boolean; is parent directory
			}
		]

	Output:
		Sorted nested dictionary
	"""
def sortFileTree(files: Any) -> object {
    sortedList = sorted(files, key=lambda (x: Any) { (x['type'], x['path']); });
    return sortedList;
}

"""Function extracted from Keras - check keras.engine.training_utils
    for the original version.

    Returns a list of batch indices (tuples of indices).
    # Arguments
        size: Integer, total size of the data to slice into batches.
        batch_size: Integer, batch size.
    # Returns
        A list of tuples of array indices.
    """
def make_batches(size: Any, batch_size: Any) -> object {
    num_batches = ((size + batch_size) - 1) // batch_size;
    return [
        ((i * batch_size), min(size, ((i + 1) * batch_size)))
        for i in range(num_batches)
    ];
}

"""[summary]
    This algorithm computes the n-th fibbonacci number
    very quick. approximate O(n)
    The algorithm use dynamic programming.

    Arguments:
        n {[int]} -- [description]

    Returns:
        [int] -- [description]
    """
def fib_list(n: Any) -> object {
    assert (n >= 0) , 'n must be a positive integer';
    list_results = [0, 1];
    for i in range(2, (n + 1)) {
        list_results.append((list_results[(i - 1)] + list_results[(i - 2)]));
    }
    return list_results[n];
}

"""
    Returns a list containing the items found in sublists of lst.
    """
def flatten(lst: Any) -> object {
    return [item for sublist in lst for item in sublist];
}
